      if (name === 'bulk') { const bj = await loadJob('bulk'); bj.status = 'paused'; bj.message = e.message; await saveJob(bj); shareBulk('paused', e.message); }
      log(e.message, status === 'paused' ? 'warn' : 'err'); setNow(e.message);
