  /* 종류별 '읽어 낸 내용'(대조용)과 '비어 보이지 않음' 기준 — 실제 저장에 쓰는 같은 파서 */
  const pubUsed = (url) => PUB.read('used', url, (g) => P.parseUsedPage(g.doc), (g) => { const u = P.parseUsedPage(g.doc); return !!(u && u.listings && u.listings.length); });
